package main

import (
	"fmt"
	"math"
)

// Place names for "Near": the closest town (or Seattle neighbourhood) to a
// node, from a built-in list (places_data.go, generated by
// scripts/places/gen-places.py) covering the western US and BC. Nothing is
// looked up online.

type place struct {
	name   string
	region string // state or province code, or "Seattle" for a neighbourhood
	lat    float64
	lon    float64
}

const (
	// Beyond this the node is described by its distance from the place.
	placeNearKm = 8.0
	// Beyond this the list has nothing useful to say.
	placeMaxKm = 150.0
)

// nearPlace names the place closest to lat/lon: "Woodinville, WA",
// "First Hill, Seattle", or "12 km from Sequim, WA" when the closest is more
// than placeNearKm away. Empty without a position or nothing within
// placeMaxKm.
func nearPlace(lat, lon float64) string {
	if (lat == 0 && lon == 0) || math.IsNaN(lat) || math.IsNaN(lon) {
		return ""
	}
	best, bestKm := -1, math.MaxFloat64
	for i := range placeList {
		p := &placeList[i]
		// Cheap box test before the haversine: a degree of latitude is
		// ~111 km, of longitude less, so this never drops a closer place.
		if math.Abs(p.lat-lat) > bestKm/111 {
			continue
		}
		if d := haversineKm(lat, lon, p.lat, p.lon); d < bestKm {
			best, bestKm = i, d
		}
	}
	if best < 0 || bestKm > placeMaxKm {
		return ""
	}
	p := placeList[best]
	label := p.name + ", " + p.region
	if bestKm > placeNearKm {
		return fmt.Sprintf("%.0f km from %s", bestKm, label)
	}
	return label
}
